# owner: platform
import unittest

from hourglass.rounding import round_span, rounded_labels
from hourglass.parsing import parse_span
from hourglass.models import Span


class RoundSpanTests(unittest.TestCase):
    def test_rounds_to_nearest_step(self):
        self.assertEqual(round_span(Span(542, 1018), 15), Span(540, 1020))

    def test_exact_half_goes_up(self):
        self.assertEqual(round_span(Span(67, 127), 15), Span(60, 120))
        self.assertEqual(round_span(Span(68, 128), 15), Span(75, 135))

    def test_aligned_span_is_unchanged(self):
        self.assertEqual(round_span(Span(540, 1020), 30), Span(540, 1020))

    def test_end_of_day_stays_valid(self):
        self.assertEqual(round_span(Span(1400, 1439), 30), Span(1410, 1440))

    def test_collapsing_span_raises(self):
        with self.assertRaises(ValueError):
            round_span(Span(540, 544), 15)


class LabelTests(unittest.TestCase):
    def test_label_format(self):
        spans = [parse_span("09:02-17:14")]
        self.assertEqual(rounded_labels(spans, 15), ["09:00-17:15 (8h 15m)"])

    def test_one_label_per_span(self):
        spans = [parse_span("08:00-12:00"), parse_span("13:00-13:20")]
        labels = rounded_labels(spans, 10)
        self.assertEqual(labels, ["08:00-12:00 (4h 00m)", "13:00-13:20 (0h 20m)"])

    def test_empty_list(self):
        self.assertEqual(rounded_labels([], 15), [])


class StepValidationTests(unittest.TestCase):
    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 45, 90):
            with self.subTest(step=step):
                with self.assertRaises(ValueError):
                    rounded_labels([Span(60, 120)], step)

    def test_bad_step_raises_even_without_spans(self):
        with self.assertRaises(ValueError):
            rounded_labels([], 0)

    def test_good_steps_accepted(self):
        for step in (1, 5, 10, 15, 20, 30, 60):
            with self.subTest(step=step):
                self.assertEqual(len(rounded_labels([Span(60, 180)], step)), 1)
